---@class ActLuckInfoData
ActLuckInfoEvent = class("ActLuckInfoEvent")
function ActLuckInfoEvent:initialize()
    self.awardList= { }
    self.isUnLuckyDraw=true
    self.callBack=nil
end

---@param msg SC_ActLuckAward
function ActLuckInfoEvent:SetDataByMsg(msg,isUnLuckyDraw , callBack)
    for i = 1, #msg.hitVal do
        table.insert(self.awardList,msg.hitVal[i])
    end
    self.isUnLuckyDraw=isUnLuckyDraw
    self.callBack=callBack
end


---@field GetDataTimeString  fun(param:self):string @可选重写 获取活动持续时间
---@field GetDataTime fun(param:self):number
---@field GetUIModuleID fun(param:self):string
---@field gameObject  CS.UnityEngine.GameObject
---@field actConfig  act_bussiness_config_cell
---@class Page_CommonActLuckInfoView
Page_CommonActLuckInfoView = class("Page_CommonActLuckInfoView",Page_CommonActViewBase)

function Page_CommonActLuckInfoView:GetPageName()
    return "Page_CommonActLuckInfoView"
end

function Page_CommonActLuckInfoView:initialize()

end

function Page_CommonActLuckInfoView:OnAwake()
    self.cardTransParent=UIUtil.GetChild("cardTransParent",self.gameObject)
end

function Page_CommonActLuckInfoView:OnOpen()
    self.finalAward=0
    self.cs_Start_turnTabel={}
    local count = self.cardTransParent.transform.childCount
    CommonHelper:SetText("time/###time", self.gameObject,self:GetDataTimeString())
    for i = 1, count do
        self:SetItem(i)
    end
    CommonHelper:HButtonSetCallback("drawBtn",self.gameObject,function()
        if self.isUnLuckyDraw then
            if self.selectIndexOne~=-1 and self.selectIndexTwo~=-1 then
                CommonFestivalSubSystem:Get():SendMsg_LuckAward(self.actConfig.C_ID)
            else
                CommonTipsHelper:ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.LuckDrawUnSelectCard))
            end
        else
            CommonTipsHelper:ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.LuckDrawAchieved))
        end
    end)
    CommonHelper:HButtonSetCallback("BtnHelp",self.gameObject,function(btn)
        CommonHelper:ShowHelpView(PageDetailType.ActLuckInfo,nil,nil,true    )
    end)
    self.BtnProb=CommonHelper:HButtonSetCallback("BtnProb",self.gameObject,function (hbtn)
        CommonHelper:ShowHelpView(PageDetailType.ActLuckInfoProb,nil,HelpStyleType.YellowStyle,true)
    end)
    CommonHelper:SetHButtonClick(self.BtnProb,HVersionManager:GetServerFunctionIsFlag(CdnFunctionKey.BtnProb),true)
end

function Page_CommonActLuckInfoView:RefreshNum()
    local str=1
    if  self.selectIndexOne == -1 and  self.selectIndexTwo ==-1 then
        str = 2
    elseif  self.selectIndexOne ~= -1 and  self.selectIndexTwo ~=-1 then
        str = 0
    end
    str = self.isUnLuckyDraw and str or 0
    CommonHelper:SetText("DarwNum/###darwNum",self.gameObject,str)
end

function Page_CommonActLuckInfoView:RequestOpen()
    CommonFestivalSubSystem:Get():SendMsg_LuckInfo(self.actConfig.C_ID)
end

----@param isUnLuckyDraw boolean
function Page_CommonActLuckInfoView:Refresh(data)
    self.isUnLuckyDraw = data[1]
    self.selectIndexOne = -1
    self.selectIndexTwo = -1
    self:RefreshNum()
end

function Page_CommonActLuckInfoView:ShowAward(data)
    ---@type ActLuckInfoData
    self.actLuckInfoData =data[1]
    self.isUnLuckyDraw=self.actLuckInfoData.isUnLuckyDraw
    for i = 1,#self.actLuckInfoData.awardList do
        if i==1 then
            self.finalAward = self.actLuckInfoData.awardList[i]
            self:DoPlayAni(self.selectIndexOne,self.finalAward)
        elseif i==2 then
            local tempAward =self.actLuckInfoData.awardList[i]
            self.finalAward = tempAward>self.finalAward and tempAward or self.finalAward
            self:DoPlayAni(self.selectIndexTwo,tempAward)
        end
    end
end

function Page_CommonActLuckInfoView:DoPlayAni(index,num)
    local  itemObj = self.cardTransParent.transform:GetChild(index-1).gameObject
    local ui_tween_turn_rot = itemObj:GetComponent(typeof(TweenRotation))
    ui_tween_turn_rot:ResetToBeginning()
    ui_tween_turn_rot:PlayForward()
    local cs_Start_turn = cs_coroutine.start(function()
        coroutine.yield(CS.UnityEngine.WaitForSeconds(0.75))
        self:SetItem(index,num)
        coroutine.yield(CS.UnityEngine.WaitForSeconds(0.25))
        if num==self.finalAward and  self.actLuckInfoData and  self.actLuckInfoData.callBack then
            self.actLuckInfoData.callBack()
            self.actLuckInfoData=nil
            CommonHelper:CloseGuideScreenEffectUIMask()
        end
    end)
    if #self.cs_Start_turnTabel==0 then
        CommonHelper:PlayGuideScreenEffectUIMask()
    end
    table.insert(self.cs_Start_turnTabel,cs_Start_turn)
end

function Page_CommonActLuckInfoView:SetItem(index,num)
    local  itemObj = self.cardTransParent.transform:GetChild(index-1).gameObject
    if num then
        CommonHelper:SetText("###iconNum",itemObj,string.format(CommonHelper:GetTempStr_Default(TemplateStringID.CollectWordNumSign),num))
    end
    CommonHelper:SetGameObjectActive("blackmask",itemObj, num and self.finalAward~=num)
    local checked = (self.selectIndexOne == index or self.selectIndexTwo == index) and not self.isUnLuckyDraw
    CommonHelper:SetGameObjectActive("reversecommonImg",itemObj,num == nil)
    CommonHelper:SetGameObjectActive("frontcommonImg",itemObj,num ~= nil)
    CommonHelper:SetGameObjectActive("checkedImg",itemObj,checked)
    CommonHelper:HButtonSetCallback("btnOnClick",itemObj,function()
        if  self.isUnLuckyDraw then
            if checked then
                if self.selectIndexOne == index then
                    self.selectIndexOne =-1
                elseif self.selectIndexTwo == index then
                    self.selectIndexTwo =-1
                end
            elseif self.selectIndexOne == -1 then
                self.selectIndexOne = index
            elseif self.selectIndexTwo == -1 then
                self.selectIndexTwo = index
            end
            checked = self.selectIndexOne == index or self.selectIndexTwo == index
            CommonHelper:SetGameObjectActive("checkedImg",itemObj,checked)
            self:RefreshNum()
        end
    end)
end

function Page_CommonActLuckInfoView:GetRedPointActive()
    return RedPointManager:Get():GetValue(RedPointID.S_LuckInfo)
end

function Page_CommonActLuckInfoView:OnClose()
    for i = 1, #self.cs_Start_turnTabel do
        if  self.cs_Start_turnTabel[i]  then
            cs_coroutine.stop( self.cs_Start_turnTabel[i])
        end
    end
    self.cs_Start_turnTabel={}
    if self.finalAward and  self.actLuckInfoData and  self.actLuckInfoData.callBack then
        self.actLuckInfoData.callBack()
        self.actLuckInfoData=nil
        CommonHelper:CloseGuideScreenEffectUIMask()
    end
end